{"kind":"tool","id":"B3ozoPjmzWk","toolName":"write_file","input":{"path":"src/App.tsx","instructions":"Main GiftRoll screen with two buttons","content":"import { useState } from 'react'
import './App.css'

/**
 * Telegram Mini App: GiftRoll
 * Тема берётся из CSS-переменных Telegram (--tg-theme-*),
 * которые Телеграм подставляет сам в обоих режимах (светлом/тёмном).
 */
function App() {
  const [connected, setConnected] = useState(false)
  const [opened, setOpened] = useState(0)

  const handleConnect = () => {
    // TODO: заменить на TON Connect (TONConnectUIProvider в main.tsx)
    setConnected((v) => !v)
  }

  const handleOpenCase = () => {
    setOpened((n) => n + 1)
  }

  return (
    <div className="app">
      <header className="app__header">
        <h1 className="app__title">GiftRoll</h1>
        <p className="app__subtitle">Открывай кейсы и забирай подарки</p>
      </header>

      <main className="app__main">
        <div className={`case ${opened > 0 ? 'case--opened' : ''}`}>
          <div className="case__glow" />
          <div className="case__body">🎁</div>
          <div className="case__label">
            {opened > 0 ? `Открыто кейсов: ${opened}` : 'Твой кейс ждёт'}
          </div>
        </div>

        <div className="app__actions">
          <button
            type="button"
            className={`btn btn--secondary ${connected ? 'btn--connected' : ''}`}
            onClick={handleConnect}
          >
            {connected ? 'Кошелёк подключён ✓' : 'Подключить кошелёк'}
          </button>

          <button type="button" className="btn btn--primary" onClick={handleOpenCase}>
            Открыть кейс
          </button>
        </div>

        <footer className="app__status">
          <span className={`dot ${connected ? 'dot--on' : 'dot--off'}`} />
          {connected ? 'TON-кошелёк активен' : 'Кошелёк не подключён'}
        </footer>
      </main>
    </div>
  )
}

export default App
"}}
