{"kind":"tool","id":"B3slLLjjyq8","toolName":"write_file","input":{"path":"src/index.css","instructions":"Global styles with Telegram CSS variable defaults","content":"/*
 * Глобальные стили.
 * Цвета берутся из CSS-переменных Telegram (--tg-theme-*),
 * которые автоматически подставляются в светлой и тёмной теме.
 * Значения по умолчанию нужны, когда страница открыта вне Telegram
 * (например, локально в браузере).
 */
:root {
  --tg-theme-bg-color: #ffffff;
  --tg-theme-text-color: #000000;
  --tg-theme-hint-color: #999999;
  --tg-theme-link-color: #2481cc;
  --tg-theme-button-color: #2481cc;
  --tg-theme-button-text-color: #ffffff;
  --tg-theme-secondary-bg-color: #f4f4f5;
  --tg-theme-section-bg-color: #ffffff;
  --tg-theme-section-header-text-color: #2481cc;
  --tg-theme-subtitle-text-color: #999999;
  --tg-theme-destructive-text-color: #ff3b30;
}

* {
  box-sizing: border-box;
}

html,
body,
#root {
  height: 100%;
}

body {
  margin: 0;
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial,
    sans-serif;
  background-color: var(--tg-theme-bg-color);
  color: var(--tg-theme-text-color);
  -webkit-font-smoothing: antialiased;
  -webkit-tap-highlight-color: transparent;
  overscroll-behavior: none;
}

button {
  font-family: inherit;
}
"}}
{"kind":"tool","id":"B3tAwlvS6YA","toolName":"write_file","input":{"path":"src/App.css","instructions":"Screen styles based on Telegram CSS variables","content":"/* Экран GiftRoll — всё на Telegram CSS-переменных */

.app {
  min-height: 100%;
  display: flex;
  flex-direction: column;
  gap: 24px;
  padding: 20px 16px calc(20px + env(safe-area-inset-bottom));
  background-color: var(--tg-theme-bg-color);
  color: var(--tg-theme-text-color);
}

.app__header {
  text-align: center;
  padding-top: 12px;
}

.app__title {
  margin: 0;
  font-size: 34px;
  font-weight: 800;
  letter-spacing: -0.5px;
  background: linear-gradient(135deg, var(--tg-theme-button-color), #7b61ff);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}

.app__subtitle {
  margin: 6px 0 0;
  font-size: 15px;
  color: var(--tg-theme-hint-color);
}

.app__main {
  display: flex;
  flex-direction: column;
  gap: 28px;
  flex: 1;
}

/* Кейс */
.case {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
  padding: 32px 20px;
  border-radius: 20px;
  background-color: var(--tg-theme-secondary-bg-color);
  overflow: hidden;
  user-select: none;
}

.case__glow {
  position: absolute;
  inset: -40%;
  background: radial-gradient(
    circle at center,
    color-mix(in srgb, var(--tg-theme-button-color) 35%, transparent),
    transparent 60%
  );
  opacity: 0.6;
  pointer-events: none;
  transition: opacity 0.3s ease;
}

.case__body {
  position: relative;
  font-size: 84px;
  line-height: 1;
  filter: drop-shadow(0 10px 20px rgba(0, 0, 0, 0.25));
  animation: float 3s ease-in-out infinite;
}

.case--opened .case__body {
  animation: pop 0.5s ease;
}

.case__label {
  position: relative;
  font-size: 14px;
  font-weight: 600;
  color: var(--tg-theme-subtitle-text-color);
}

@keyframes float {
  0%,
  100% {
    transform: translateY(0);
  }
  50% {
    transform: translateY(-8px);
  }
}

@keyframes pop {
  0% {
    transform: scale(1);
  }
  40% {
    transform: scale(1.25) rotate(-6deg);
  }
  100% {
    transform: scale(1);
  }
}

/* Кнопки */
.app__actions {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.btn {
  appearance: none;
  border: none;
  border-radius: 14px;
  padding: 15px 20px;
  font-size: 16px;
  font-weight: 700;
  cursor: pointer;
  transition:
    transform 0.12s ease,
    filter 0.12s ease,
    opacity 0.12s ease;
}

.btn:active {
  transform: scale(0.97);
}

.btn--primary {
  background-color: var(--tg-theme-button-color);
  color: var(--tg-theme-button-text-color);
}

.btn--primary:hover {
  filter: brightness(1.06);
}

.btn--secondary {
  background-color: var(--tg-theme-secondary-bg-color);
  color: var(--tg-theme-text-color);
  border: 1px solid color-mix(in srgb, var(--tg-theme-hint-color) 40%, transparent);
}

.btn--connected {
  color: var(--tg-theme-button-color);
  border-color: var(--tg-theme-button-color);
}

/* Статус */
.app__status {
  margin-top: auto;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  font-size: 13px;
  color: var(--tg-theme-hint-color);
}

.dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
}

.dot--on {
  background-color: #31d158;
  box-shadow: 0 0 8px #31d158;
}

.dot--off {
  background-color: var(--tg-theme-hint-color);
}
"}}


