import { allCases, findNftPrize } from './src/data/cases.js'

const me = {
  id: '11111111',
  firstName: 'Dev',
  lastName: null,
  username: 'dev',
  photoUrl: null,
  balance: 50_000,
  inventoryCount: 0,
  dailyBonusAvailable: false,
  createdAt: new Date().toISOString(),
}

function json(res: http.ServerResponse, status: number, body: unknown) {
  res.writeHead(status, { 'Content-Type': 'application/json' })
  res.end(JSON.stringify(body))
}

http
  .createServer((req, res) => {
    const url = req.url ?? '/'

    if (req.method === 'GET' && url.startsWith('/api/me')) {
      return json(res, 200, me)
    }
    if (req.method === 'GET' && url.startsWith('/api/cases')) {
      return json(res, 200, { cases: allCases })
    }
    if (req.method === 'GET' && url.startsWith('/api/inventory')) {
      return json(res, 200, { items: [] })
    }
    if (req.method === 'POST' && url.startsWith('/api/upgrader/upgrade')) {
      let raw = ''
      req.on('data', (chunk) => (raw += chunk))
      req.on('end', () => {
        const body = JSON.parse(raw || '{}') as {
          starsBet?: number
          chance?: number
          targetNftId?: string
        }
        const target = body.targetNftId ? findNftPrize(body.targetNftId) : null
        const totalBet = body.starsBet ?? 0
        json(res, 200, {
          win: false,
          winAmount: 0,
          multiplier: 95 / (body.chance ?? 1),
          totalBet,
          receivedNft: null,
          remainingStars: 0,
          target: target?.id ?? null,
        })
      })
      return
    }

    json(res, 404, { error: 'not found' })
  })
  .listen(3000, () => {
    console.log('mock api on 3000')
  })
"}}


