import { env } from '../config/env.js'
import { prisma } from '../db/prisma.js'
import { DepositError, MAX_DEPOSIT_STARS, MIN_DEPOSIT_STARS } from './deposit.js'

const CRYPTO_PAY_API = 'https://pay.crypt.bot/api'
/** Курс: 1 USD = 100 звёзд. */
