type CryptoApiResponse<T> = { ok: boolean; result?: T; error?: { code?: number; name?: string; message?: string } }

async function callCryptoPay<T>(method: string, body: Record<string, unknown>): Promise<T> {
  if (!env.CRYPTO_PAY_TOKEN) throw new DepositError('CRYPTO_PAY_NOT_CONFIGURED', 'Крипто-оплата временно недоступна', 503)
  const res = await fetch(`${CRYPTO_PAY_API}/${method}`, {
    method: 'POST',
    headers: { 'Crypto-Pay-API-Token': env.CRYPTO_PAY_TOKEN, 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  })
  const data = await res.json().catch(() => null) as CryptoApiResponse<T> | null
  if (!res.ok || !data?.ok) throw new DepositError('CRYPTO_PAY_ERROR', ..., 502)
  return data.result as T
}
